contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount1, uint amount2, uint amount3) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount1) + (amount2) + (amount3)); require(amount1 <= 1000000000000000000000000000000); require(amount2 <= 1000000000000000000000000000000); require(amount3 <= 1000000000000000000000000000000);
        require(address(this).balance >= amount1 + amount2 + amount3);
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        c.deposit{value: amount1}(); if (__ESBMC_reverted()) return;
        c.deposit{value: amount2}(); if (__ESBMC_reverted()) return;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        c.deposit{value: amount3}(); if (__ESBMC_reverted()) return;
        assert(address(c).balance == cBefore + amount3 &&
               thisBefore - address(this).balance == amount3);
    }
    receive() external payable {}
}

