pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount1, uint256 amount2, uint256 amount3) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        amount3 = bound(amount3, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount1 + amount2 + amount3);
        uint cBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        try c.deposit{value: amount1}() {} catch { return; }
        try c.deposit{value: amount2}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        try c.deposit{value: amount3}() {} catch { return; }
        assertTrue(address(c).balance == cBefore + amount3 &&
               thisBefore - address(this).balance == amount3);
    }

    function testFuzz_run(uint256 amount1, uint256 amount2, uint256 amount3) public {
        _run(amount1, amount2, amount3);
    }

    receive() external payable {}
}
